package com.taskflow.exception;
import com.taskflow.dto.ApiDtos.ApiError;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.ConstraintViolationException;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.bind.MissingServletRequestParameterException;import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;import org.springframework.security.access.AccessDeniedException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler {
 @ExceptionHandler(NotFoundException.class) ResponseEntity<ApiError> notFound(NotFoundException e,HttpServletRequest r){return error(404,"Not Found",e.getMessage(),r,Map.of());}
 @ExceptionHandler({BadRequestException.class,IllegalArgumentException.class}) ResponseEntity<ApiError> bad(RuntimeException e,HttpServletRequest r){return error(400,"Bad Request",e.getMessage(),r,Map.of());}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String>d=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->d.putIfAbsent(x.getField(),x.getDefaultMessage()));return error(400,"Validation Failed","One or more fields are invalid",r,d);}
 @ExceptionHandler(ConstraintViolationException.class) ResponseEntity<ApiError> constraints(ConstraintViolationException e,HttpServletRequest r){return error(400,"Validation Failed",e.getMessage(),r,Map.of());}
 @ExceptionHandler(AccessDeniedException.class) ResponseEntity<ApiError> denied(AccessDeniedException e,HttpServletRequest r){return error(403,"Forbidden",e.getMessage(),r,Map.of());}
 @ExceptionHandler({HttpMessageNotReadableException.class,MissingServletRequestParameterException.class,MethodArgumentTypeMismatchException.class}) ResponseEntity<ApiError> malformed(Exception e,HttpServletRequest r){return error(400,"Bad Request","Request parameters or JSON values are invalid",r,Map.of());}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<ApiError> conflict(DataIntegrityViolationException e,HttpServletRequest r){return error(409,"Conflict","The operation conflicts with existing data (email must be unique)",r,Map.of());}
 private ResponseEntity<ApiError> error(int s,String title,String message,HttpServletRequest r,Map<String,String>d){return ResponseEntity.status(s).body(new ApiError(Instant.now().toString(),s,title,message,r.getRequestURI(),d));}
}
